const texts=["NO, WE WON'T SHUT UP.","NO, WE WON'T GO AWAY.","NO, WE'RE NOT MOVING ON.","NO, IT'S NOT JUST US.","YES, YOU WILL LISTEN."];let currentIndex=0;const heroText=document.getElementById("heroText");function changeText(){setTimeout(()=>{heroText.textContent=texts[currentIndex],currentIndex=(currentIndex+1)%texts.length},500)}heroText.textContent=texts[0],setInterval(changeText,6e3);